<?php
namespace App\Http\Controllers;use App\Services\ResourceEditingSessionService;use Illuminate\Http\Request;
final class ResourceEditingSessionController extends Controller{public function __construct(private ResourceEditingSessionService $sessions){}public function index(Request $r,string $type,string $resource){return ['data'=>$this->sessions->active($r->user(),$type,$resource)];}public function store(Request $r,string $type,string $resource){$r->validate(['user_id'=>'prohibited','expires_at'=>'prohibited']);return response()->json(['data'=>$this->sessions->start($r->user(),$type,$resource)],201);}public function heartbeat(Request $r,string $type,string $resource,string $session){return ['data'=>$this->sessions->heartbeat($r->user(),$type,$resource,$session)];}public function destroy(Request $r,string $type,string $resource,string $session){$this->sessions->release($r->user(),$type,$resource,$session);return response()->noContent();}}
